assets["/mud/index.html"] = MUD_HTML;
assets["/mud-client.js"] = MUD_CLIENT;
const types = {".html":"text/html; charset=utf-8",".json":"application/json; charset=utf-8",".atom":"application/atom+xml; charset=utf-8",".xml":"application/xml; charset=utf-8",".txt":"text/plain; charset=utf-8",".ttl":"text/turtle; charset=utf-8",".jsonld":"application/ld+json; charset=utf-8",".js":"text/javascript; charset=utf-8"};
function assetPath(pathname) {
  if (pathname === "/") return "/index.html";
  const clean = pathname.replace(/\/$/, "");
  return /\.[a-z0-9]+$/i.test(clean) ? clean : clean + "/index.html";
}
export default { async fetch(request, env) {
  const url = new URL(request.url);
  if (url.hostname === "gui.561.group" && !await admitMudOperator(request, env)) return refuseUnadmittedMudOperator();
  if (url.hostname === "gui.561.group" && url.pathname === "/api/mud") return handleMudApi(request, "read", createCloudMudServices(env, workspaceTerritoryArtifact));
  if (url.hostname === "gui.561.group" && url.pathname === "/api/mud/play") return handleMudApi(request, "play", createCloudMudServices(env, workspaceTerritoryArtifact));
  if (url.hostname === "gui.561.group" && url.pathname === "/api/mud/conversation") return handleMudApi(request, "conversation", createCloudMudServices(env, workspaceTerritoryArtifact));
  if (url.hostname === "gui.561.group" && url.pathname === "/") url.pathname = "/mud";
  if (url.hostname === "market.561.group" && url.pathname === "/") url.pathname = "/market";
  if (url.hostname === "561.group" && url.pathname === "/market") return Response.redirect("https://market.561.group/", 308);
  const key = assetPath(url.pathname);
  const body = assets[key];
  if (body === undefined) return new Response("Not found\n", { status: 404, headers: security("text/plain; charset=utf-8") });
  const type = types[key.slice(key.lastIndexOf("."))] || "application/octet-stream";
  return new Response(body, { status: 200, headers: security(type) });
} };
function security(type) { return {
  "content-type": type, "cache-control": "public, max-age=300",
  "content-security-policy": "default-src 'self'; style-src 'self' 'unsafe-inline'; base-uri 'self'; frame-ancestors 'none'; object-src 'none'",
  "strict-transport-security": "max-age=31536000; includeSubDomains",
  "x-content-type-options": "nosniff", "referrer-policy": "no-referrer",
  "x-frame-options": "DENY", "permissions-policy": "geolocation=(), microphone=(), camera=()"
}; }
